<?php require_once __DIR__.'/includes/functions.php';$q=trim($_GET['q']??'');$page_title=$q?'Search: '.$q:'Search';require __DIR__.'/includes/header.php'; ?><section class="section-head"><h1>Search</h1></section><form class="search big"><input name="q" value="<?=e($q)?>" placeholder="Search articles..." required><button>Search</button></form><?php if($q!==''){$s=$pdo->prepare("SELECT a.*,c.name category_name,c.slug category_slug FROM articles a JOIN categories c ON c.id=a.category_id WHERE a.status='published' AND (a.title LIKE ? OR a.excerpt LIKE ? OR a.content_html LIKE ?) ORDER BY a.published_at DESC");$like='%'.$q.'%';$s->execute([$like,$like,$like]);echo '<div class="results">';foreach($s as $a){echo '<article class="result"><a class="category" href="'.article_url($a['slug']).'">'.e($a['category_name']).'</a><h2><a href="'.article_url($a['slug']).'">'.e($a['title']).'</a></h2><p>'.e($a['excerpt']).'</p></article>';}echo '</div>';} require __DIR__.'/includes/footer.php'; ?>
